using SignalCluster.Core;
var builder=WebApplication.CreateBuilder(args);builder.Services.AddCors(o=>o.AddDefaultPolicy(p=>p.WithOrigins("http://localhost:5173","http://127.0.0.1:5173").AllowAnyHeader().AllowAnyMethod()));var app=builder.Build();app.UseCors();app.MapGet("/",()=>Results.Ok(new{name="SignalCluster.Service",version="0.2.0",mode="simulation-only"}));app.MapGet("/health",()=>Results.Ok(new{status="healthy",utc=DateTimeOffset.UtcNow}));app.MapGet("/build-info",()=>Results.Ok(new{product="SignalCluster",buildName="SignalCluster Virtual Observatory Simulator",buildId="SC-SIM-2026.10.29-001",version="0.2.0",developer="ArkansasIo",targetRuntime=".NET 8",hardwareMode="simulation-only"}));app.MapGet("/radio/status",()=>Results.Ok(new{deviceName="SignalCluster Virtual Radio Receiver (SC-VRR-01)",simulatedOnly=true,rfInputConnected=false,rfTransmitEnabled=false,supportedModes=new[]{"pulsar","tone","noise","am"}}));app.MapPost("/algorithms/dispersion-delay",(DispersionRequest r)=>{try{return Results.Ok(new{delayMilliseconds=SignalAlgorithms.DispersionDelayMilliseconds(r.DispersionMeasure,r.LowFrequencyMHz,r.HighFrequencyMHz)});}catch(ArgumentOutOfRangeException e){return Results.BadRequest(new{error=e.Message});}});app.MapPost("/algorithms/fft-magnitude",(FftRequest r)=>{try{return Results.Ok(new{magnitude=SignalAlgorithms.FftMagnitude(r.Samples)});}catch(ArgumentException e){return Results.BadRequest(new{error=e.Message});}});app.Run();record DispersionRequest(double DispersionMeasure,double LowFrequencyMHz,double HighFrequencyMHz);record FftRequest(double[] Samples);
